class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        from collections import Counter

        len_s, len_p = len(s), len(p)
        if len_s < len_p:
            return []

        p_count = Counter(p)
        s_count = Counter()
        result = []

        for i in range(len_s):
            # 添加右端字符
            s_count[s[i]] += 1

            # 移除左端超出窗口的字符
            if i >= len_p:
                left_char = s[i - len_p]
                s_count[left_char] -= 1
                if s_count[left_char] == 0:
                    del s_count[left_char]

            # 比较窗口频率与 p 的频率
            if s_count == p_count:
                result.append(i - len_p + 1)

        return result
